{
  "mechanisms": [
    {
      "name": "neutral_initialization",
      "title": "Neutral Q-value Initialization",
      "description": "Stage 2 model-free Q-values are initialized to a neutral value of 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage2_mf = np.zeros((2, 2)) + 0.5",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Stage 2 Q-values decay towards a neutral center of 0.5 on every trial, representing forgetting or uncertainty.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage2_mf += decay_rate * (0.5 - q_stage2_mf)",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture",
      "description": "Stage 1 action values are computed as a weighted mixture of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net_1 = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A perseveration bonus is added to the Stage 1 logit of the action chosen on the previous trial.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [0, 5]
        }
      ],
      "evidence": "if prev_action_1 != -1:\n            logits_1[prev_action_1] += stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "counterfactual_updating",
      "title": "Counterfactual Updating",
      "description": "The Q-value of the unchosen Stage 2 action is updated using an assumed opposite reward.",
      "params": [
        {
          "name": "cf_weight",
          "bounds": [0, 1]
        }
      ],
      "evidence": "cf_target = 1.0 if r <= 0 else 0.0\n            pe_cf = cf_target - q_stage2_mf[s_idx, 1-a2]\n            q_stage2_mf[s_idx, 1-a2] += learning_rate * cf_weight * pe_cf",
      "expressible_in_slots": true
    }
  ]
}
